using System;using System.Collections.Generic;using System.Reflection;using PptEase.Host;
public class PageTags {public Dictionary<string,string> Data=new Dictionary<string,string>();public string Item(string k){return Data.ContainsKey(k)?Data[k]:"";}public void Add(string k,string v){Data[k]=v;}}
public class PageFill{public int Type=1;public float Transparency=0;}
public class PageShadow{public int Visible=0;}
public class PageText{public int HasText=0;}
public class PageShape{public int Type=1,AutoShapeType=1,Visible=-1;public float Left=10,Top=20,Width=100,Height=40,Rotation=0;public string Name="rectangle";public PageTags Tags=new PageTags();public PageFill Fill=new PageFill();public PageShadow Shadow=new PageShadow();public PageText TextFrame=new PageText();public bool Applied,Deleted;public void PickUp(){}public void Apply(){Applied=true;}public void Delete(){Deleted=true;}}
public class PageShapes{public List<PageShape> Items=new List<PageShape>();public int Count{get{return Items.Count;}}public PageShape Item(int i){return Items[i-1];}public PageShape AddShape(int type,float l,float t,float w,float h){var s=new PageShape{AutoShapeType=type,Left=l,Top=t,Width=w,Height=h};Items.Add(s);return s;}}
public class PageSource{public PageShapes Shapes=new PageShapes();}
public class PageSlide:PageSource{public PageSource Master=new PageSource(),CustomLayout=new PageSource();}
class PageObjectTests{static void Main(){var host=new Connect();var run=typeof(Connect).GetMethod("CreatePageObjects",BindingFlags.NonPublic|BindingFlags.Instance);var s=new PageSlide();var rect=new PageShape();rect.Tags.Add("PPTEASE_SPAWN_OBJECT","A");s.CustomLayout.Shapes.Items.Add(rect);run.Invoke(host,new object[]{s});if(s.Shapes.Count!=1||s.Shapes.Item(1).Type==14||!s.Shapes.Item(1).Applied)throw new Exception("Must create styled non-placeholder shape");run.Invoke(host,new object[]{s});if(s.Shapes.Count!=1)throw new Exception("Duplicate generated");s.Shapes.Item(1).Left=55;run.Invoke(host,new object[]{s});if(s.Shapes.Item(1).Left!=55)throw new Exception("Local edit overwritten");var transparent=new PageShape();transparent.Fill.Transparency=.5f;transparent.Tags.Add("PPTEASE_SPAWN_OBJECT","B");s.CustomLayout.Shapes.Items.Add(transparent);run.Invoke(host,new object[]{s});if(s.Shapes.Count!=1)throw new Exception("Unsupported translucent source duplicated");Console.WriteLine("PASS ordinary shape, copied appearance call, idempotence, local edits, translucent exclusion. Fake host tests only; Office interaction pending.");}}
